        return [(2, 30, 10, [2, 5], [1, 3], [7, 5], 17),
                (3, 24, 16, [2, 3, 10], [2, 3, 15], [6, 5, 2], 24),
                (3, 16, 5, [6, 3, 1], [5, 2, 1], [4, 7, 2], 13),
